"import json
import pathlib

root = pathlib.Path(r"C:\Users\bssho\AppData\Local\CapCut\User Data\Projects\com.lveditor.draft")
out = []
for p in sorted(root.rglob("draft_content.json")):
    if ".cloud_cache" in str(p) or "hermes" in str(p):
        continue
    try:
        dc = json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        continue
    for v in dc.get("materials", {}).get("videos", []):
        name = v.get("material_name", "")
        vpath = v.get("path", "")
        if v.get("type") == "photo" or "logo" in name.lower() or "로고" in name or "png" in vpath.lower():
            out.append(f"{p.parent.name}/{p.name}: type={v.get('type')} name={name} path={vpath} id={v.get('id')}")
            # find segment using this id
            for ti, tr in enumerate(dc.get("tracks", [])):
                for si, s in enumerate(tr.get("segments", [])):
                    if s.get("material_id") == v.get("id"):
                        st = s["target_timerange"]["start"] / 1e6
                        du = s["target_timerange"]["duration"] / 1e6
                        clip = s.get("clip", {})
                        out.append(f"   -> Track {ti} [{si}] {st:.2f}s~{st+du:.2f}s scale={clip.get('scale')} transform={clip.get('transform')}")
    # Also check subdrafts in draft_content.json!
    for sd in dc.get("subdrafts", []):
        out.append(f"{p.parent.name}/{p.name} SUBDRAFT: name={sd.get('name')} id={sd.get('id')}")
        sdc = sd.get("draft", {})
        for v in sdc.get("materials", {}).get("videos", []):
            out.append(f"   SUB_VID: type={v.get('type')} name={v.get('material_name')} path={v.get('path')}")
        for tx in sdc.get("materials", {}).get("texts", []):
            cobj = json.loads(tx.get("content") or "{}")
            out.append(f"   SUB_TXT: {cobj.get('text')}")

