"import json, pathlib

draft_root = pathlib.Path(r"C:\Users\bssho\AppData\Local\CapCut\User Data\Projects\com.lveditor.draft")
for name in ["미러비교(9대16)", "직관성(9대16)", "폴스타 4 릴스"]:
    p = draft_root / name / "draft_content.json"
    if not p.exists(): continue
    dc = json.loads(p.read_text(encoding="utf-8"))
    print(f"=== {name} ===")
    vmap = {v["id"]: pathlib.Path(v.get("path","")).name for v in dc.get("materials", {}).get("videos", [])}
    tmap = {}
    for t in dc.get("materials", {}).get("texts", []):
        try:
            tmap[t["id"]] = json.loads(t.get("content", "{}")).get("text", "").replace("\n", " / ")
        except Exception:
            pass
    for ti, tr in enumerate(dc.get("tracks", [])):
        if tr.get("type") in ("video", "text"):
            print(f"  Track {ti} ({tr.get('type')}):")
            for seg in tr.get("segments", []):
                trange = seg.get("target_timerange", {})
                st = trange.get("start", 0)/1e6
                du = trange.get("duration", 0)/1e6
                mid = seg.get("material_id")
                clip = seg.get("clip", {})
                tf = clip.get("transform", {})
                sc = clip.get("scale", {})
                label = vmap.get(mid) or tmap.get(mid) or mid
                print(f"    {st:5.2f}s ~ {st+du:5.2f}s ({du:4.2f}s): {label} | pos=({tf.get('x',0):.2f}, {tf.get('y',0):.2f}) scale=({sc.get('x',1):.2f}, {sc.get('y',1):.2f})")
"

